    trapExamples: [{ question: "「ものさしの めもりを 読む とき」どこから 見る？\nア「ななめから」\nイ「まうえから」", wrongAnswer: "ア", trapExplanation: "ななめから 見ると、めもりが ずれて 見える。", correctAnswer: "イ", correctExplanation: "めもりの まうえから 見る。ななめからだと ずれて 見えるから。" }],
